input.query:
SELECT count(distinct p.Ensembl)
FROM proteinatlas p
LEFT JOIN (
  SELECT Gene FROM cancer_prognostic_data WHERE Cancer = 'Kidney Renal Clear Cell Carcinoma (TCGA)'
) c ON p.Ensembl = c.Gene
